    sol = solve_ivp(lambda t,y: rhs(t,y,P), (0, times.max()), [P['E0']], t_eval=times, rtol=1e-8, atol=1e-10)
    return sol.y[0]
def predict(df, p):
    global P
    P = p
    return per_dose(df, solve_one)

